    "battle_1_name": "Changshao",
    "battle_1_brief": "Lu, 684 BC. Cao Gui let Qi beat the drums three times, then struck. Mate in one: iron bolt.",
    "battle_2_name": "Chengpu",
    "battle_2_brief": "632 BC. Jin drew the Chu center forward and closed both wings. Mate in one: double rooks.",
    "battle_3_name": "Boju",
    "battle_3_brief": "506 BC. Wu drove deep into Chu and took Ying. Mate in one: horse behind the cannon.",
    "battle_4_name": "Lize",
    "battle_4_brief": "478 BC. Yue crossed the river in two bodies and broke Wu. Mate in one: pocket horse.",
    "battle_5_name": "Guiling",
    "battle_5_brief": "354 BC. Qi marched on Wei’s capital to lift the siege of Zhao. Mate in one: double cannon.",
    "battle_6_name": "Maling",
    "battle_6_brief": "342 BC. Sun Bin reduced his campfires and waited in the pass. Mate in one: fishing horse.",
    "battle_7_name": "Changping",
    "battle_7_brief": "260 BC. Qin cut Zhao’s army off and closed the ring. Mate in one: double rooks.",
    "battle_8_name": "Jimo",
    "battle_8_brief": "279 BC. Tian Dan opened the city and drove into the Yan camp at night. Mate in one: pocket horse.",
    "battle_9_name": "Jingxing",
    "battle_9_brief": "204 BC. Han Xin put his army with its back to the river, then turned. Mate in one: face-to-face generals.",
    "battle_10_name": "Chen Cang",
    "battle_10_brief": "206 BC. The plank road was a feint. The army came out at Chen Cang. Mate in one: double cannon.",
    "battle_11_name": "Weishui",
    "battle_11_brief": "204 BC. Han Xin dammed the river, drew the enemy across, then let the water go. Mate in one: horse behind the cannon.",
    "battle_12_name": "Gaixia",
    "battle_12_brief": "202 BC. Han armies closed on Xiang Yu from every side. Mate in one: double rooks.",
    "battle_13_name": "Guandu",
    "battle_13_brief": "AD 200. Cao Cao burned Yuan Shao’s supplies at Wuchao. Mate in one: iron bolt.",
    "battle_14_name": "Red Cliffs",
    "battle_14_brief": "AD 208. Fire ran through the chained fleet on the Yangtze. Mate in one: double cannon.",
    "battle_15_name": "Hanzhong",
    "battle_15_brief": "AD 219. Huang Zhong took Dingjun Mountain and Xiahou Yuan fell. Mate in one: fishing horse.",
    "battle_16_name": "Yiling",
    "battle_16_brief": "AD 222. Lu Xun held back, then burned the Shu camps. Mate in one: pocket horse.",
    "battle_17_name": "Feishui",
    "battle_17_brief": "383. Fu Jian’s host started to fall back and could not be stopped. Mate in one: face-to-face generals.",
    "battle_18_name": "Hulao",
    "battle_18_brief": "621. Li Shimin broke Dou Jiande in front of the pass. Mate in one: corner horse.",
    "battle_19_name": "Yancheng",
    "battle_19_brief": "1140. Yue Fei’s riders broke the Jin cavalry at Yancheng. Mate in one: horse behind the cannon.",
    "battle_20_name": "Poyang Lake",
    "battle_20_brief": "1363. Zhu Yuanzhang’s fire ships broke Chen Youliang’s tower ships. Mate in one: heaven-and-earth cannons.",
